def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_D = 0
    recent_D = 0
    recent_start = n - 6
    if recent_start < 0:
        recent_start = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_D += 1
            if i >= recent_start:
                recent_D += 1

    opp_C = n - opp_D

    opD_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opD_streak += 1
        else:
            break

    if recent_D == 0:
        start = 100
        if opp_D == 0:
            start = 10
        elif opp_D == 1 and opp_C >= 30:
            start = 55
        elif opp_D == 2 and opp_C >= 50:
            start = 75
        elif opp_D == 3 and opp_C >= 70:
            start = 88
        elif opp_D == 4 and opp_C >= 80:
            start = 96
        if n >= start:
            if n == start:
                return 'D'
            if n == start + 1:
                return 'C'
            return 'D'

    if opp_D == 0:
        return 'C'

    if opp_C == 0:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_D * 3 <= opp_C:
                return 'C'
            return 'D'
        if opD_streak == 1 and recent_D == 1 and opp_D * 5 <= opp_C:
            return 'C'
        if opD_streak >= 3 and opp_D * 3 <= opp_C and rng.random() < 0.10:
            return 'C'
        if recent_D >= 3 and opp_D * 3 <= opp_C and rng.random() < 0.10:
            return 'C'
        return 'D'

    if opp_D * 2 > opp_C:
        return 'D'

    if recent_D >= 3:
        return 'D'

    return 'C'
